async function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('my-day-local:'+new URL('./',import.meta.url).pathname,1);req.onupgradeneeded=()=>req.result.createObjectStore('space');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function loadData(){db=await openDb();return new Promise((resolve,reject)=>{const req=db.transaction('space').objectStore('space').get('main');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function storedValue(key){return new Promise((resolve,reject)=>{const request=db.transaction('space').objectStore('space').get(key);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
function storeValue(key,value){return new Promise((resolve,reject)=>{const tx=db.transaction('space','readwrite');tx.objectStore('space').put(structuredClone(value),key);tx.oncomplete=()=>resolve();tx.onerror=tx.onabort=()=>reject(tx.error);});}
function persist(sync=true,metadata=null){const snapshot=structuredClone(data);saveQueue=saveQueue.catch(()=>false).then(()=>new Promise(resolve=>{if(!db){storageOk=false;render();notify('本机存储不可用，请先导出备份');resolve(false);return;}const tx=db.transaction('space','readwrite'),space=tx.objectStore('space');space.put(snapshot,'main');if(metadata)space.put(structuredClone(metadata),'sync-meta');tx.oncomplete=()=>{storageOk=true;resolve(true);};tx.onerror=tx.onabort=()=>{storageOk=false;render();notify('保存失败，请导出备份并检查存储空间');resolve(false);};}));return saveQueue.then(ok=>{if(ok&&sync)cloud?.changed().catch(()=>{});return ok;});}
