 const all=recordsFor(e,['0000','9999']),last=[...all].sort((a,b)=>b.date.localeCompare(a.date))[0],r=recordsFor(e,effectiveRange(e,scope)),s=stats(r),isActive=e.startDate<=today()&&(!e.endDate||e.endDate>=today());
 const meta=`${e.type==='count'?'次数':e.type==='duration'?'时长':'数值'}${s.days?' · '+s.days+'天':''}`;
