function renderPeriodMonth(month){const d=parseDay(month),year=d.getFullYear(),m=d.getMonth(),offset=new Date(year,m,1).getDay(),active=month.slice(0,7)===periodDate.slice(0,7);return`<div class="period-month-block ${active?'active':''}" data-month="${month}" style="height:${periodMonthRows(month)*64}px"><div class="period-days">${'<span class="period-day-slot empty"></span>'.repeat(offset)}${Array.from({length:monthDays(year,m)},(_,i)=>{const date=`${year}-${pad(m+1)}-${pad(i+1)}`,info=dayInfo(data.period,date,month,today()),isToday=date===today();return`<div class="period-day-slot"><button class="period-day ${info.actual?'period-on':info.predicted?'predicted':info.fertile?'ovulation':''} ${date===periodSelected?'selected':''} ${isToday?'is-today':''}" data-action="period-day" data-date="${date}" aria-label="${fmt(date)}${info.actual?'，经期':info.predicted?'，预测经期':info.fertile?'，排卵期':''}" tabindex="${active?'0':'-1'}"><span>${isToday?'今':i+1}</span>${info.ovulationDay?'<small class="ovulation-caption">排卵日</small>':''}${info.hasRecord?'<i class="period-record-dot"></i>':''}</button></div>`;}).join('')}</div></div>`;}
function bindPeriodCalendar(){const viewport=$('#period-month-scroll');if(!viewport)return;const block=$('.period-month-block.active',viewport);viewport.scrollTop=block.offsetTop;let timer;viewport.addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(!viewport.isConnected||page!=='period')return;const blocks=$$('.period-month-block',viewport),nearest=blocks.reduce((best,next)=>Math.abs(next.offsetTop-viewport.scrollTop)<Math.abs(best.offsetTop-viewport.scrollTop)?next:best);if(nearest.dataset.month.slice(0,7)!==periodDate.slice(0,7)){periodSelections[periodDate.slice(0,7)]=periodSelected;periodDate=nearest.dataset.month;periodSelected=periodSelections[periodDate.slice(0,7)]||periodDate;render();}},160);},{passive:true});}
function renderPeriodHistory(){const rows=historyItems(data.period,today());return rows.length?rows.map((row,i)=>`<button class="period-cycle" data-action="period-history-day" data-id="${row.id}"><div class="period-cycle-main"><span>${i===0?'开始于 '+row.start.slice(5).replace('-','/'):row.start.slice(5).replace('-','/')+' ~ '+row.rangeEnd.slice(5).replace('-','/')}</span><div class="cycle-strip">${row.days.slice(0,40).map(day=>`<i class="${day.period?'bleeding':''} ${day.hasRecord?'recorded':''}"></i>`).join('')}</div></div><span class="cycle-length">${row.duration}/${row.cycleLength}天</span></button>`).join(''):'<p class="guide">暂无记录</p>';}
async function performPeriodAction(action){if(periodSelected>today())return;const info=dayInfo(data.period,periodSelected,periodDate,today());try{if(action==='start')startPeriod(data.period,periodSelected,today());else if(action==='end')endPeriod(data.period,periodSelected,today());else if(action==='cancel-cycle'&&info.cycle)cancelPeriodCycle(data.period,info.cycle.id);else if(action==='undo-end'&&info.cycle)undoPeriodEnd(data.period,info.cycle.id);if(await persist())render();}catch(error){notify(error.message||'未能修改经期记录');}}
const periodSelections={};
const periodHistoryFilter={from:"",to:""};
function periodHistoryView(){const total=summaryStats(data.period,today()),rows=historyItems(data.period,today()).filter(c=>(!periodHistoryFilter.from||c.start>=periodHistoryFilter.from)&&(!periodHistoryFilter.to||c.start<=periodHistoryFilter.to));return`<header class="native-header">${ib('back','period-back','返回经期')}<h1>经期统计</h1>${ib('trash','period-history-clear','清除经期历史')}</header><div class="period-history-filters"><button data-action="period-filter-from">${periodHistoryFilter.from||'开始日期'}⌄</button><span>—</span><button data-action="period-filter-to">${periodHistoryFilter.to||'结束日期'}⌄</button></div><div class="period-history-overview"><p>累计完成经期记录 ${total.completed} 次</p><div><span><strong>${total.averageDuration??'—'}<small>天</small></strong><label>平均经期</label></span><span><strong>${total.averageCycle??'—'}<small>天</small></strong><label>平均周期</label></span></div></div><div class="form-box period-history">${rows.map(c=>`<button class="period-cycle" data-action="period-history-day" data-id="${c.id}"><div class="period-cycle-main"><span>${c.start.slice(5).replace('-','/')} ~ ${c.rangeEnd.slice(5).replace('-','/')}</span><div class="cycle-strip">${c.days.slice(0,40).map(d=>`<i class="${d.period?'bleeding':''} ${d.hasRecord?'recorded':''}"></i>`).join('')}</div></div><span class="cycle-length">${c.duration}/${c.cycleLength}天</span></button>`).join('')||'<p class="guide">暂无记录</p>'}</div>`;}